    "id": 4875,
    "surahId": 54,
    "surahName": "سُورَةُ القَمَرِ",
    "verseNumber": 29,
    "text": "فَنَادَوْا۟ صَاحِبَهُمْ فَتَعَاطَىٰ فَعَقَرَ"
