    "id": 5557,
    "surahId": 75,
    "surahName": "سُورَةُ القِيَامَةِ",
    "verseNumber": 6,
    "text": "يَسْـَٔلُ أَيَّانَ يَوْمُ ٱلْقِيَٰمَةِ"
