    "id": 5692,
    "surahId": 78,
    "surahName": "سُورَةُ النَّبَإِ",
    "verseNumber": 20,
    "text": "وَسُيِّرَتِ ٱلْجِبَالُ فَكَانَتْ سَرَابًا"
